const crypto = require('crypto');
const secret = String($env.INSIGHT_PROJECT_AGENT_N8N_SECRET || '');
const baseUrl = String($env.INSIGHT_APP_BASE_URL || '').replace(/\/$/, '');
if (secret.length < 32 || !baseUrl) throw new Error('Missing project-agent integration configuration');
const path = '/integrations/n8n/project-agent/events/claim/';
const body = '{}';
const timestamp = String(Math.floor(Date.now() / 1000));
const nonce = crypto.randomBytes(24).toString('base64url');
const bodyHash = crypto.createHash('sha256').update(body, 'utf8').digest('hex');
const canonical = [timestamp, nonce, 'POST', path, bodyHash].join('\n');
const signature = crypto.createHmac('sha256', secret).update(canonical, 'utf8').digest('hex');
return [{ json: { url: baseUrl + path, body, timestamp, nonce, signature } }];

const crypto = require('crypto');
const item = $input.first().json;
if (!item.event_id) return [{ json: { has_event: false } }];
const secret = String($env.INSIGHT_PROJECT_AGENT_N8N_SECRET || '');
const sortValue = value => Array.isArray(value) ? value.map(sortValue) : value && typeof value === 'object' ? Object.fromEntries(Object.keys(value).sort().map(key => [key, sortValue(value[key])])) : value;
const canonicalPayload = JSON.stringify(sortValue(item.payload));
const expected = crypto.createHmac('sha256', secret).update(canonicalPayload, 'utf8').digest('hex');
const supplied = String(item.event_signature || '');
if (expected.length !== supplied.length || !crypto.timingSafeEqual(Buffer.from(expected), Buffer.from(supplied))) throw new Error('Invalid reviewed-event signature');
if (item.payload?.event !== 'agent_run.reviewed') throw new Error('Unexpected reviewed-event type');
return [{ json: { ...item, has_event: true } }];

const crypto = require('crypto');
const reviewed = $('Validate Reviewed Event').first().json;
const requestedOutcome = String($json.body?.outcome || 'rejected');
const outcome = ['notified', 'archived', 'rejected', 'failed'].includes(requestedOutcome) ? requestedOutcome : 'rejected';
const secret = String($env.INSIGHT_PROJECT_AGENT_N8N_SECRET || '');
const baseUrl = String($env.INSIGHT_APP_BASE_URL || '').replace(/\/$/, '');
const path = '/integrations/n8n/project-agent/events/callback/';
const body = JSON.stringify({ event_id: reviewed.event_id, lease_token: reviewed.lease_token, outcome });
const timestamp = String(Math.floor(Date.now() / 1000));
const nonce = crypto.randomBytes(24).toString('base64url');
const bodyHash = crypto.createHash('sha256').update(body, 'utf8').digest('hex');
const canonical = [timestamp, nonce, 'POST', path, bodyHash].join('\n');
const signature = crypto.createHmac('sha256', secret).update(canonical, 'utf8').digest('hex');
return [{ json: { url: baseUrl + path, body, timestamp, nonce, signature, safe_archive: { event_id: reviewed.event_id, project_code: reviewed.payload.project_code, outcome } } }];
